// ***************
// Filename: frame_counter_top.sv
// Author: FPGA Cores 4 U
// Description: frame_counter with its AXI4-Lite register interface, the block
//   designs and testbenches instantiate: the register map frame_counter_regs
//   (u_regs, src/include/frame_counter_regs.sv, ID "FCNT", VERSION and DATE
//   at 0x00-0x08, the registers from 0x10) and the logic frame_counter
//   (u_core, src/frame_counter.sv), joined by the register interface
//   frame_counter_regs_if (u_regs_if). Generated by ip/scripts/regmap_gen.py
//   from frame_counter_regs.json and the ports of frame_counter: regenerate
//   after changing either. Clock - clk. Reset - synchronous active low rst_n.
// Date: 2026-10-16
module frame_counter_top #(
  parameter int NCH = 2,
  parameter int EVQ = 64,
  parameter int TS_DIV = 1
) (
  input  logic clk,
  input  logic rst_n,
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 8
  axil_if.slave s_axil,
  input  logic [NCH-1:0] eof_i,
  output logic [NCH-1:0] irq_o
);
  // register interface between the register map and the logic
  frame_counter_regs_if #(.NCH(NCH)) u_regs_if ();

  frame_counter_regs #(
    .NCH(NCH)
  ) u_regs (
    .clk,
    .rst_n,
    .s_axil(s_axil),
    .r(u_regs_if)
  );
  frame_counter #(
    .NCH(NCH),
    .EVQ(EVQ),
    .TS_DIV(TS_DIV)
  ) u_core (
    .clk,
    .rst_n,
    .eof_i,
    .irq_o,
    .regs(u_regs_if)
  );
endmodule
